package com.yuegang.zhihui.order.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.yuegang.zhihui.common.mq.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.*;import org.springframework.scheduling.annotation.*;@Configuration(proxyBeanMethods=false)@ConditionalOnProperty(name="ygh.mq.enabled",havingValue="true")class OrderOutboxConfiguration{@Bean(destroyMethod="close")DomainEventPublisher orderEventPublisher(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t){return new RocketMqDomainEventPublisher("ygh-order-producer",n,t);}@Bean(destroyMethod="close")OrderWalletEventConsumer orderWalletEventConsumer(@Value("${ygh.mq.nameserver}")String n,@Value("${ygh.mq.topic:YGH_DOMAIN_EVENTS}")String t,OrderInventoryFacade s,RefundInventoryCoordinator r,ObjectMapper o){return new OrderWalletEventConsumer(n,t,s,r,o);}@Bean OrderOutboxJob orderOutboxJob(JdbcTemplate j,DomainEventPublisher p,OrderInventoryFacade f){return new OrderOutboxJob(new JdbcOutboxDispatcher(j,p,"order_outbox"),f);}static final class OrderOutboxJob{private final JdbcOutboxDispatcher d;private final OrderInventoryFacade f;OrderOutboxJob(JdbcOutboxDispatcher d,OrderInventoryFacade f){this.d=d;this.f=f;}@Scheduled(fixedDelayString="${ygh.mq.dispatch-delay:1000}")public void dispatch(){d.dispatch();}@Scheduled(fixedDelayString="${ygh.order.expiry-delay:30000}")public void closeExpired(){f.closeExpired();}}}
